<div class="toolbar"><form class="toolbar grow" method="get" style="margin:0"><input type="search" name="q" value="<?= e($s) ?>" placeholder="Search name, reference, contact…"><select name="status" data-autosubmit><option value="">All statuses</option><?php foreach (REQ_STATUS as $x): ?><option <?= $st === $x ? 'selected' : '' ?> value="<?= $x ?>"><?= $x ?> (<?= (int) ($counts[$x] ?? 0) ?>)</option><?php endforeach; ?></select><button class="btn btn-ghost btn-sm">Search</button></form><a class="btn btn-ghost btn-sm" href="<?= e(url('/admin/requests', ['q' => $s, 'status' => $st, 'export' => 'csv'])) ?>"><?= icon('download', 15) ?> Export CSV</a></div>
<div class="table-wrap"><table class="t"><thead><tr><th>Reference</th><th>Customer</th><th>Request</th><th>Status</th><th>Payment</th><th>Received</th></tr></thead><tbody>
<?php foreach ($items as $r): ?><tr><td><a href="/admin/requests/<?= e($r['ref']) ?>"><strong><?= e($r['ref']) ?></strong></a></td><td><?= e($r['name']) ?><div class="muted xs"><?= e($r['contact']) ?></div></td><td><?= e($r['service']) ?><div class="muted xs"><?= e($r['need']) ?></div></td>
<td><?= badge($r['status'], ['New' => 'amber', 'Won' => 'green', 'Lost' => 'red', 'Quoted' => 'blue'][$r['status']] ?? '') ?></td><td><?= e($r['payment']) ?></td><td class="muted xs"><?= e(ago($r['created_at'])) ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="6" class="muted center" style="padding:30px">No requests match.</td></tr><?php endif; ?></tbody></table></div><?= pager($pg, '/admin/requests', ['q' => $s, 'status' => $st]) ?>
